using namespace std;

int main() {
    const long NUM = 1000000;
    long n;

    vector<bool> primeNum(NUM + 1, true);
    primeNum[0] = primeNum[1] = false;

    for (long i = 2; i * i <= NUM; ++i) {
        if (primeNum[i]) {
            for (long j = i * i; j <= NUM; j += i) {
                primeNum[j] = false;
            }
        }
    }

    // Precompute the cumulative count of primes
    vector<long> primeCount(NUM + 1, 0);
    for (long i = 1; i <= NUM; i++) {
        primeCount[i] = primeCount[i - 1] + (primeNum[i] ? 1 : 0);
    }

    while (scanf("%ld", &n) != EOF) {
        printf("%ld\n", primeCount[n]);
    }

    return 0;
}

